from .money import MAX_AMOUNT, format_amount, from_cents, parse_amount, to_cents


def make_invoice(amounts):
    # Exact type check: only a plain list is accepted (not str, tuple, None, ...).
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    # Summing integer cents is exact and independent of the decimal context.
    total_cents = 0
    for item in amounts:
        total_cents += to_cents(parse_amount(item))
    total = from_cents(total_cents)
    if total > MAX_AMOUNT:
        raise ValueError("total must not exceed 1000000.00")
    return {"total": format_amount(total), "count": len(amounts)}

