import re
from decimal import Decimal

MAX_AMOUNT = Decimal("1000000.00")

# ASCII-only: [0-9] is a literal range, so non-ASCII digits never match.
_AMOUNT_STRING = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def parse_amount(value):
    """Return value as an exact Decimal with exponent -2.

    Accepts Decimal objects, integers (not bool) and ASCII strings matching
    [+-]?[0-9]+(?:\\.[0-9]+)?. Everything else raises ValueError. The result
    never depends on the caller's decimal context.
    """
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, bool):
        raise ValueError("bool is not an amount")
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str):
        if _AMOUNT_STRING.fullmatch(value) is None:
            raise ValueError(f"malformed amount string: {value!r}")
        amount = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    return _require_cents(amount)


def _require_cents(amount):
    # Only comparisons and as_tuple()/Decimal() construction here: none of
    # these round or depend on the context precision.
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount must not exceed 1000000.00")
    _, digits, exponent = amount.as_tuple()
    if exponent >= -2:
        return Decimal((0, digits + (0,) * (exponent + 2), -2))
    dropped = -2 - exponent  # digits strictly below the cent place
    kept = len(digits) - dropped
    # kept <= 0 means the value is below 0.01 and nonzero, so it cannot be
    # a whole number of cents. Otherwise the dropped digits must all be zero.
    if kept <= 0 or any(digits[kept:]):
        raise ValueError("amount is not exactly representable in cents")
    return Decimal((0, digits[:kept], -2))


def to_cents(amount):
    """Exact integer cents for an amount returned by parse_amount."""
    _, digits, _ = amount.as_tuple()
    return int("".join(map(str, digits)))


def from_cents(cents):
    """Exact Decimal with exponent -2 for a non-negative integer of cents."""
    whole, fraction = divmod(cents, 100)
    return Decimal(f"{whole}.{fraction:02d}")


def format_amount(value):
    return format(value, ".2f")
